/** The file of a /pair* path (/pair, /pair/, /pair/index.html, /pair/pair.js, /pair/pair.css), or null. */
export function pairPageFile(pathname) {
  if (pathname === '/pair' || pathname === '/pair/' || pathname === '/pair/index.html') return PAIR_PAGE_FILES['index.html']
  if (pathname === '/pair/pair.js') return PAIR_PAGE_FILES['pair.js']
  if (pathname === '/pair/pair.css') return PAIR_PAGE_FILES['pair.css']
  return null
}
